-- V001: esquema base de NEXO, traducido de nexo/database/nexo.sql (MySQL / InnoDB).
-- Conversiones (detalle en nexo/docs/auditoria_mysql_postgresql.md):
--   INT UNSIGNED AUTO_INCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY (cubre todo el rango sin signo)
--   TINYINT(1)                  -> BOOLEAN
--   TINYINT UNSIGNED (semestre) -> SMALLINT con CHECK 1..12 (regla que ya valida la app)
--   ENUM(...)                   -> TEXT con CHECK
--   DATETIME                    -> TIMESTAMPTZ (la app trabaja en America/Mexico_City)
--   FULLTEXT(titulo, contenido) -> índice GIN con to_tsvector('spanish', ...)
--   ON UPDATE CURRENT_TIMESTAMP -> trigger (V002)
--   InnoDB indexa solas las llaves foráneas; PostgreSQL no: se crean los índices aquí.
--   utf8mb4_unicode_ci (no distingue mayúsculas): correo se guarda en minúsculas (CHECK) y
--   la unicidad de materias usa lower().

SET LOCAL search_path TO nexo, public;

-- ---------------------------------------------------------------
-- PBI-01 Cuentas, acceso y roles
-- ---------------------------------------------------------------
CREATE TABLE usuarios (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    correo VARCHAR(150) NOT NULL,
    contrasena_hash VARCHAR(255) NOT NULL,
    rol TEXT NOT NULL DEFAULT 'estudiante',
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT usuarios_correo_unico UNIQUE (correo),
    CONSTRAINT usuarios_correo_minusculas CHECK (correo = lower(correo)),
    CONSTRAINT usuarios_rol_valido CHECK (rol IN ('estudiante', 'docente', 'moderador'))
);
COMMENT ON TABLE usuarios IS 'Cuentas con correo institucional (TR-01).';
COMMENT ON COLUMN usuarios.contrasena_hash IS 'password_hash() de PHP (bcrypt). Nunca la contraseña en claro.';
COMMENT ON COLUMN usuarios.correo IS 'Siempre en minúsculas: la app lo normaliza y el CHECK lo garantiza.';

CREATE TABLE recuperaciones (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    token_hash CHAR(64) NOT NULL,
    expira_en TIMESTAMPTZ NOT NULL,
    usado BOOLEAN NOT NULL DEFAULT FALSE,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT recuperaciones_token_unico UNIQUE (token_hash)
);
CREATE INDEX recuperaciones_usuario_idx ON recuperaciones (usuario_id);
COMMENT ON TABLE recuperaciones IS 'Enlaces de un solo uso para restablecer la contraseña (SHA-256 del token, 1 hora).';

-- ---------------------------------------------------------------
-- PBI-02 Perfiles y taxonomía de materias
-- ---------------------------------------------------------------
CREATE TABLE perfiles (
    usuario_id BIGINT PRIMARY KEY REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    carrera VARCHAR(100) NULL,
    semestre SMALLINT NULL,
    biografia VARCHAR(500) NULL,
    habilidades VARCHAR(500) NULL,
    intereses VARCHAR(500) NULL,
    actualizado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT perfiles_semestre_valido CHECK (semestre BETWEEN 1 AND 12)
);
COMMENT ON TABLE perfiles IS 'Perfil académico 1:1 con usuarios (RC-05).';
COMMENT ON COLUMN perfiles.habilidades IS 'Etiquetas separadas por comas, sin repetidos (normalizar_etiquetas en PHP).';

CREATE TABLE materias (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    carrera VARCHAR(100) NOT NULL,
    semestre SMALLINT NOT NULL,
    CONSTRAINT materias_semestre_valido CHECK (semestre BETWEEN 1 AND 12)
);
-- Equivale a UNIQUE KEY materia_unica (nombre, carrera) con intercalación que no distingue mayúsculas.
CREATE UNIQUE INDEX materias_unica ON materias (lower(nombre), lower(carrera));
COMMENT ON TABLE materias IS 'Catálogo de materias por carrera y semestre (paquete 1.3.3).';

CREATE TABLE usuario_materias (
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    materia_id BIGINT NOT NULL REFERENCES materias (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    PRIMARY KEY (usuario_id, materia_id)
);
CREATE INDEX usuario_materias_materia_idx ON usuario_materias (materia_id);
COMMENT ON TABLE usuario_materias IS 'Materias cursadas por cada usuario (N:M).';

-- ---------------------------------------------------------------
-- PBI-03 Publicaciones y adjuntos
-- ---------------------------------------------------------------
CREATE TABLE publicaciones (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    materia_id BIGINT NULL REFERENCES materias (id) ON DELETE SET NULL ON UPDATE NO ACTION,
    tipo TEXT NOT NULL DEFAULT 'contenido',
    titulo VARCHAR(150) NOT NULL,
    contenido TEXT NOT NULL,
    resguardada BOOLEAN NOT NULL DEFAULT FALSE,
    estado TEXT NOT NULL DEFAULT 'visible',
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    actualizado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT publicaciones_tipo_valido CHECK (tipo IN ('contenido', 'pregunta')),
    CONSTRAINT publicaciones_estado_valido CHECK (estado IN ('visible', 'oculta'))
);
CREATE INDEX publicaciones_fecha_idx ON publicaciones (creado_en);
CREATE INDEX publicaciones_usuario_idx ON publicaciones (usuario_id);
CREATE INDEX publicaciones_materia_idx ON publicaciones (materia_id);
-- Equivalente del FULLTEXT de MySQL; lo usará la búsqueda del PBI-05 (Sprint 3).
CREATE INDEX publicaciones_busqueda_idx ON publicaciones
    USING gin (to_tsvector('spanish', titulo || ' ' || contenido));
COMMENT ON TABLE publicaciones IS 'Contenidos y preguntas (RC-11, RC-08).';
COMMENT ON COLUMN publicaciones.resguardada IS 'true: los demás ven "Estudiante resguardado" en lugar del autor.';
COMMENT ON COLUMN publicaciones.estado IS 'oculta: retirada por moderación; solo la ven su autor y los moderadores.';

CREATE TABLE adjuntos (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    publicacion_id BIGINT NOT NULL REFERENCES publicaciones (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    nombre_original VARCHAR(255) NOT NULL,
    archivo VARCHAR(60) NOT NULL,
    tipo_mime VARCHAR(120) NOT NULL,
    tamano BIGINT NOT NULL,
    es_imagen BOOLEAN NOT NULL DEFAULT FALSE,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT adjuntos_tamano_valido CHECK (tamano >= 0)
);
CREATE INDEX adjuntos_publicacion_idx ON adjuntos (publicacion_id);
COMMENT ON TABLE adjuntos IS 'Metadatos de imágenes y archivos; el archivo vive en nexo/uploads/ con nombre aleatorio.';

-- ---------------------------------------------------------------
-- PBI-04 Participación escalonada (guardar, votar, comentar)
-- ---------------------------------------------------------------
CREATE TABLE comentarios (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    publicacion_id BIGINT NOT NULL REFERENCES publicaciones (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    contenido TEXT NOT NULL,
    resguardado BOOLEAN NOT NULL DEFAULT FALSE,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX comentarios_publicacion_idx ON comentarios (publicacion_id);
CREATE INDEX comentarios_usuario_idx ON comentarios (usuario_id);
COMMENT ON TABLE comentarios IS 'Respuestas a publicaciones; pueden ser resguardadas.';

CREATE TABLE votos (
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    publicacion_id BIGINT NOT NULL REFERENCES publicaciones (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (usuario_id, publicacion_id)
);
CREATE INDEX votos_publicacion_idx ON votos (publicacion_id);
COMMENT ON TABLE votos IS 'Voto "útil" de un usuario a una publicación (N:M).';

CREATE TABLE guardados (
    usuario_id BIGINT NOT NULL REFERENCES usuarios (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    publicacion_id BIGINT NOT NULL REFERENCES publicaciones (id) ON DELETE CASCADE ON UPDATE NO ACTION,
    creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (usuario_id, publicacion_id)
);
CREATE INDEX guardados_publicacion_idx ON guardados (publicacion_id);
COMMENT ON TABLE guardados IS 'Publicaciones guardadas por cada usuario; base del panel del PBI-05.';
